from typing import Any, Dict, Optional


OPENAI_API_HOST = "https://api.openai.com/v1/moderations"
OPENAI_MODERATION_MODEL = "omni-moderation-latest"


def _post_json(url: str, payload: Dict[str, Any], api_key: str, timeout: int = 30) -> Dict[str, Any]:
    data = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(
        url,
        data=data,
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
        },
        method="POST",
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        return json.loads(response.read().decode("utf-8"))


def check_live_caption_safety(
    text: str,
    api_key: Optional[str] = None,
    model: str = OPENAI_MODERATION_MODEL,
) -> Dict[str, Any]:
    key = api_key or os.getenv("OPENAI_API_KEY")
    if not key:
        raise ValueError("OPENAI_API_KEY is required")
    payload = {"model": model, "input": text}
    result = _post_json(OPENAI_API_HOST, payload, key)
    output = result.get("results", [{}])[0]
    flagged = bool(output.get("flagged", False))
    categories = output.get("categories", {})
    category_scores = output.get("category_scores", {})
    return {
        "flagged": flagged,
        "categories": categories,
        "category_scores": category_scores,
